import urllib.request, urllib.parse, re; word='hello'; url='https://www.signasl.org/sign/'+urllib.parse.quote(word, safe=''); req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'}); html=urllib.request.urlopen(req).read().decode('utf-8', errors='replace'); match = re.search(r'<video[^>]+src=\"([^\"]+)\"', html) or re.search(r'<source[^>]+src=\"([^\"]+)\"', html); print(urllib.parse.urljoin(url, match.group(1)) if match else 'not found')
